from collections import Counter

class Solution:
    def reorganizeString(self, s: str) -> str:
        counts = Counter(s)
        result = []

        def backtrack(prev: str) -> bool:
            if len(result) == len(s):
                return True
            for ch in list(counts):
                if counts[ch] > 0 and ch != prev:
                    counts[ch] -= 1
                    result.append(ch)
                    if backtrack(ch):
                        return True
                    result.pop()
                    counts[ch] += 1
            return False

        return "".join(result) if backtrack("") else ""

