from collections import Counter

class Solution:
    def reorganizeString(self, s: str) -> str:
        n = len(s)
        counts = Counter(s)
        if max(counts.values()) > (n + 1) // 2:
            return ""

        chars = sorted(counts, key=lambda ch: -counts[ch])
        result = [""] * n
        index = 0
        for ch in chars:
            for _ in range(counts[ch]):
                if index >= n:
                    index = 1
                result[index] = ch
                index += 2
        return "".join(result)

